'use strict';

// MODULES //

var PathEncoding = require( '@stdlib/plot/vega/mark/path/encoding' );


// MAIN //

/**
* Returns defaults.
*
* @private
* @returns {Object} default options
*
* @example
* var o = defaults();
* // returns {...}
*/
function defaults() {
	return {
		// Visual encoding rules for path mark properties:
		'encoding': new PathEncoding(),

		// Mark type:
		'type': 'path'
	};
}


// EXPORTS //

module.exports = defaults;
